import csv, re, json
from datetime import date

RUN_DATE = date(2026,6,30)

def parse_amount(s):
    s = s.strip().replace('$','').replace(',','').replace(' ','')
    neg = False
    if s.startswith('-'):
        neg = True
        s = s[1:]
    if s.startswith('(') and s.endswith(')'):
        neg = True
        s = s[1:-1]
    val = float(s)
    return -val if neg else val

def parse_date(s):
    return date.fromisoformat(s.strip())

def norm_id(s):
    return s.strip().lower()

def norm_partner(s):
    return s.strip().lower()

with open('input/commission_lines.csv', newline='') as f:
    lines = list(csv.DictReader(f))
with open('input/customer_master.csv', newline='') as f:
    customers = {r['customer_id'].strip(): r for r in csv.DictReader(f)}
with open('input/netsuite_revenue_june.csv', newline='') as f:
    ledger_rows = list(csv.DictReader(f))
with open('input/commission_exceptions.csv', newline='') as f:
    exceptions = list(csv.DictReader(f))
with open('input/co_sell_register.csv', newline='') as f:
    co_sell = list(csv.DictReader(f))

# Deduplicate ledger by posting_id; same posting_id repeated is the same posting, not a second amount.
ledger_unique = {}
for r in ledger_rows:
    pid = r['posting_id'].strip()
    if pid not in ledger_unique:
        ledger_unique[pid] = r
ledger = list(ledger_unique.values())

# Net June revenue by normalized deal
net_june = {}
ledger_customers = {}
for r in ledger:
    d = norm_id(r['deal_ref'])
    pd = parse_date(r['posting_date'])
    if pd.year == 2026 and pd.month == 6:
        net_june[d] = net_june.get(d, 0) + parse_amount(r['amount_usd'])
        # ledger customer for June postings (assume consistent customer per deal)
        ledger_customers[d] = r['customer_id'].strip()

# Active VP overrides by deal
overrides = {}
for e in exceptions:
    if e['status'].strip().lower() == 'active':
        if parse_date(e['effective_from']) <= RUN_DATE <= parse_date(e['effective_to']):
            d = norm_id(e['deal_id'])
            # If multiple active overrides exist, keep the one encountered; here only one active per deal matters
            overrides[d] = float(e['approved_rate_pct'])

# Co-sell registration validity
co_sell_by_deal = {}
for r in co_sell:
    d = norm_id(r['deal_id'])
    co_sell_by_deal.setdefault(d, []).append(r)

def co_sell_valid(d, deal_lines):
    rows = co_sell_by_deal.get(d, [])
    if not rows:
        return False, None
    if any(r['status'].strip().lower() != 'active' for r in rows):
        return False, None
    partners = sorted(norm_partner(r['partner']) for r in rows)
    line_partners = sorted(norm_partner(l['source_report']) for l in deal_lines)
    if partners != line_partners:
        return False, None
    if len(rows) != len(deal_lines):
        return False, None
    if abs(sum(float(r['share_pct']) for r in rows) - 100) > 1e-9:
        return False, None
    shares = {norm_partner(r['partner']): float(r['share_pct']) for r in rows}
    if len(set(norm_partner(l['source_report']) for l in deal_lines)) != len(deal_lines):
        return False, None
    return True, shares

deal_lines = {}
for l in lines:
    d = norm_id(l['deal_id'])
    deal_lines.setdefault(d, []).append(l)

def end_user_type(cust_id):
    c = customers[cust_id]
    if c['account_class'].strip().lower() == 'house':
        return 'house'
    fid = parse_date(c['first_invoice_date'])
    if date(2025,7,1) <= fid <= RUN_DATE:
        return 'new'
    return 'renewal'

standard_rate = {'new': 8.0, 'renewal': 4.0, 'house': 0.0}

findings = []
rows = []
for l in lines:
    d = norm_id(l['deal_id'])
    deal_lines_for_d = deal_lines[d]
    is_duplicate_candidate = len(deal_lines_for_d) > 1
    valid, shares = co_sell_valid(d, deal_lines_for_d)
    is_duplicate = is_duplicate_candidate and not valid

    # customer for rate
    if d in ledger_customers:
        cust_id = ledger_customers[d]
    else:
        cust_id = l['customer_id'].strip()
    ut = end_user_type(cust_id)
    rate = standard_rate[ut]
    if d in overrides:
        rate = overrides[d]
    reported = float(l['reported_rate_pct'])
    commissionable = rate > 0

    # ledger match
    matched = None
    if commissionable:
        line_rev = float(l['revenue_usd'])
        net = net_june.get(d, 0.0)
        if valid and shares:
            share = shares.get(norm_partner(l['source_report']), 0.0)
            expected = net * share / 100.0
        else:
            expected = net
        matched = abs(expected - line_rev) <= 0.01 * line_rev

    if is_duplicate:
        code = 'DUPLICATE_LINE'
    elif commissionable and not matched:
        code = 'UNMATCHED_TO_LEDGER'
    elif abs(reported - rate) > 1e-9:
        code = 'RATE_MISMATCH'
    else:
        code = 'COMPLIANT'

    rows.append({
        'line_id': l['line_id'],
        'deal_id': l['deal_id'],
        'source_report': l['source_report'],
        'customer_used': cust_id,
        'end_user_type': ut,
        'policy_rate': rate,
        'reported_rate': reported,
        'revenue': float(l['revenue_usd']),
        'net_june': net_june.get(d, 0.0),
        'commissionable': commissionable,
        'matched': matched,
        'duplicate': is_duplicate,
        'co_sell_valid': valid,
        'code': code
    })
    if code != 'COMPLIANT':
        findings.append((l['line_id'], l['deal_id'], l['source_report'], code))

print('line_id|deal_id|source|cust|type|rate|reported|rev|net|comm|matched|dup|cosell|code')
for r in rows:
    print('|'.join(str(x) for x in [r['line_id'],r['deal_id'],r['source_report'],r['customer_used'],r['end_user_type'],r['policy_rate'],r['reported_rate'],r['revenue'],round(r['net_june'],2),r['commissionable'],r['matched'],r['duplicate'],r['co_sell_valid'],r['code']]))
print()
print('findings:', findings)
from collections import Counter
c = Counter(r['code'] for r in rows)
print('counts:', c)
print('total:', len(rows))
print('compliant:', c.get('COMPLIANT',0))
